// Vérification de la signature HMAC-SHA256 (en-tête X-MAJI-Signature).
// REMPLACER LA VALEUR DU SECRET par celle du site (option maji_webhook_secret, via `wp option get maji_webhook_secret`).
const crypto = require('crypto');
const SECRET = 'REMPLACER_PAR_LE_SECRET_DU_SITE';
const body = JSON.stringify($input.first().json.body);
const signature = $input.first().json.headers['x-maji-signature'] || '';
const expected = 'sha256=' + crypto.createHmac('sha256', SECRET).update(body).digest('hex');
if (signature !== expected) {
  throw new Error('Signature invalide — webhook rejeté');
}
return [{ json: $input.first().json.body }];

// Construit le message WhatsApp pour le gérant.
const o = $input.first().json.order;
const lines = o.items.map(i => `• ${i.qty}× ${i.name}${i.variation ? ' (' + i.variation + ')' : ''} — ${i.total} FCFA`).join('
');
const mode = o.fulfillment.mode === 'delivery' ? `Livraison — ${o.fulfillment.zone} (${o.fulfillment.fee} FCFA)` : 'Retrait sur place';
const text = `🍽 NOUVELLE COMMANDE n°${o.number}

${lines}

Total : ${o.totals.total} ${o.totals.currency}
${mode}
Client : ${o.customer.name} — ${o.customer.phone}
${o.note ? 'Note : ' + o.note : ''}`;
return [{ json: { text, phone: o.customer.phone, consent: o.customer.whatsapp_consent } }];
